'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');

const SCHEMA = `
  -- One row per click event. click_id is generated by the browser for every
  -- click, so a retried request (same click_id) can never be counted twice.
  CREATE TABLE IF NOT EXISTS click_events (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    click_id     TEXT NOT NULL UNIQUE,
    campaign     TEXT NOT NULL,
    visitor_hash TEXT NOT NULL,
    button       TEXT NOT NULL,
    created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  );
  CREATE INDEX IF NOT EXISTS idx_click_events_campaign ON click_events (campaign, button);

  -- One row per (campaign, visitor). The primary key IS the uniqueness rule.
  CREATE TABLE IF NOT EXISTS unique_clicks (
    campaign         TEXT NOT NULL,
    visitor_hash     TEXT NOT NULL,
    first_clicked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    PRIMARY KEY (campaign, visitor_hash)
  ) WITHOUT ROWID;
`;

function isBusyError(err) {
  return Boolean(err) && /database is (locked|busy)|SQLITE_BUSY/i.test(String(err.message));
}

/**
 * Opens (and initialises) the SQLite database and returns a small data-access
 * object. Every statement is prepared once and uses bound parameters only.
 */
function openStore(file) {
  if (file !== ':memory:') fs.mkdirSync(path.dirname(file), { recursive: true });
  const db = new DatabaseSync(file);
  db.exec('PRAGMA journal_mode = WAL;');
  db.exec('PRAGMA synchronous = NORMAL;');
  db.exec('PRAGMA busy_timeout = 5000;');
  db.exec(SCHEMA);

  const insertClick = db.prepare(
    'INSERT OR IGNORE INTO click_events (click_id, campaign, visitor_hash, button) VALUES (?, ?, ?, ?)'
  );
  const insertUnique = db.prepare(
    'INSERT OR IGNORE INTO unique_clicks (campaign, visitor_hash) VALUES (?, ?)'
  );
  const countClicks = db.prepare('SELECT COUNT(*) AS n FROM click_events WHERE campaign = ?');
  const countUnique = db.prepare('SELECT COUNT(*) AS n FROM unique_clicks WHERE campaign = ?');
  const countByButton = db.prepare(
    'SELECT button, COUNT(*) AS n FROM click_events WHERE campaign = ? GROUP BY button'
  );

  return {
    db, // exposed for tests and maintenance scripts

    /**
     * Records one click atomically.
     *  - same click_id again           -> { duplicate: true }  (retry, nothing changes)
     *  - new click, known visitor      -> total +1, unique unchanged
     *  - new click, first-time visitor -> total +1, unique +1
     * BEGIN IMMEDIATE takes the write lock up front, so concurrent writers
     * (even from several processes) are serialised instead of failing midway.
     */
    recordClick({ clickId, campaign, visitorHash, button }) {
      db.exec('BEGIN IMMEDIATE');
      try {
        const click = insertClick.run(clickId, campaign, visitorHash, button);
        if (Number(click.changes) === 0) {
          db.exec('COMMIT');
          return { duplicate: true, newUniqueVisitor: false };
        }
        const unique = insertUnique.run(campaign, visitorHash);
        db.exec('COMMIT');
        return { duplicate: false, newUniqueVisitor: Number(unique.changes) === 1 };
      } catch (err) {
        try {
          db.exec('ROLLBACK');
        } catch {
          /* transaction was already closed */
        }
        throw err;
      }
    },

    /** Aggregate numbers only. No visitor identifiers ever leave this function. */
    getStats(campaign) {
      const clicksByButton = {};
      for (const row of countByButton.all(campaign)) clicksByButton[row.button] = Number(row.n);
      return {
        totalClicks: Number(countClicks.get(campaign).n),
        uniqueVisitors: Number(countUnique.get(campaign).n),
        clicksByButton,
      };
    },

    close() {
      db.close();
    },
  };
}

module.exports = { openStore, isBusyError };
